import React from 'react';
/** @jsxRuntime classic */
/** @jsx jsx */
import { jsx, css } from '@emotion/react';
import { Users, Building2, BookOpen, Award } from 'lucide-react';
import { HomeConst } from '../Home.Const';

const styles = {
  container: css`
    background: linear-gradient(135deg, #1A365D 0%, #0F172A 100%);
    padding: 32px 24px;
    border-radius: 16px;
    margin: 24px 0;
    box-shadow: 0 12px 30px rgba(26, 54, 93, 0.25);
    border: 1px solid rgba(255, 255, 255, 0.1);
  `,
  grid: css`
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 24px;
    max-width: 1200px;
    margin: 0 auto;
  `,
  card: css`
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 16px;
    background: rgba(255, 255, 255, 0.05);
    border-radius: 12px;
    backdrop-filter: blur(8px);
    transition: transform 0.3s ease, background 0.3s ease;
    border: 1px solid rgba(255, 255, 255, 0.08);

    &:hover {
      transform: translateY(-4px);
      background: rgba(255, 255, 255, 0.12);
    }
  `,
  iconBox: css`
    width: 48px;
    height: 48px;
    border-radius: 12px;
    background: #DA532C;
    color: #FFFFFF;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    box-shadow: 0 4px 12px rgba(218, 83, 44, 0.35);
  `,
  statNumber: css`
    font-size: 26px;
    font-weight: 800;
    color: #FFB020; /* Gold/Yellow Accent */
    line-height: 1.2;
    font-family: inherit;
  `,
  statLabel: css`
    font-size: 13px;
    color: #E2E8F0;
    font-weight: 500;
  `
};

const icons = [<Users size={24} />, <Building2 size={24} />, <BookOpen size={24} />, <Award size={24} />];

const MetricsTicker = () => {
  const metricsData = HomeConst.MetricsTicker;

  return (
    <div css={styles.container}>
      <div css={styles.grid}>
        {metricsData.map((metric, idx) => (
          <div key={idx} css={styles.card}>
            <div css={styles.iconBox}>
              {icons[idx % icons.length]}
            </div>
            <div>
              <div css={styles.statNumber}>{metric.number}</div>
              <div css={styles.statLabel}>{metric.label}</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default MetricsTicker;
